SELECT * FROM (SELECT sub0.time AS "time", (sub0.value - lag(sub0.value) OVER (ORDER BY sub0.time)) AS "sensor.ENERGY.Total" FROM (SELECT time_bucket('1d', "time", 'Europe/Berlin') AS "time", last("sensor.ENERGY.Total", "time") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" > (time_bucket('1d', now() - interval '7d', 'Europe/Berlin') AT TIME ZONE 'Europe/Berlin' - interval '1d') AT TIME ZONE 'Europe/Berlin' GROUP BY 1 ORDER BY 1 ASC) sub0) d WHERE "time" >= time_bucket('1d', now() - interval '7d', 'Europe/Berlin') ORDER BY 1 DESC